import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BQ1gajhD.js";const x=JSON.parse('{"title":"五道营胡同","description":"","frontmatter":{},"headers":[],"relativePath":"landmarks/wudaoying-hutong.md","filePath":"landmarks/wudaoying-hutong.md","lastUpdated":1787033866000}'),n={name:"landmarks/wudaoying-hutong.md"};function o(d,t,i,s,h,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="五道营胡同" tabindex="-1">五道营胡同 <a class="header-anchor" href="#五道营胡同" aria-label="Permalink to &quot;五道营胡同&quot;">​</a></h1><p><img src="https://images.unsplash.com/photo-1535941339077-2dd1c7963098?w=1200" alt="五道营胡同"></p><blockquote><p>&quot;京城最文艺的胡同，闹市里的慢生活。&quot;</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>五道营胡同位于北京市东城区安定门内，西起安定门内大街，东至雍和宫大街，全长约600米。与商业化气息浓厚的南锣鼓巷相比，五道营胡同更安静、更文艺，被许多旅行者称为&quot;北京最文艺的胡同&quot;。这里聚集了大量独立咖啡馆、设计小店、手作工作室、书店和特色餐厅，是年轻人散步、拍照、发呆的理想去处。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>开放时间</strong></td><td style="text-align:left;">全天开放</td></tr><tr><td style="text-align:left;"><strong>门票价格</strong></td><td style="text-align:left;">免费</td></tr><tr><td style="text-align:left;"><strong>建议游玩</strong></td><td style="text-align:left;">1-2小时</td></tr><tr><td style="text-align:left;"><strong>最佳季节</strong></td><td style="text-align:left;">春秋季</td></tr><tr><td style="text-align:left;"><strong>交通方式</strong></td><td style="text-align:left;">地铁2号线安定门站或5号线雍和宫站</td></tr><tr><td style="text-align:left;"><strong>地址</strong></td><td style="text-align:left;">北京市东城区五道营胡同</td></tr></tbody></table><h2 id="历史沿革" tabindex="-1">历史沿革 <a class="header-anchor" href="#历史沿革" aria-label="Permalink to &quot;历史沿革&quot;">​</a></h2><h3 id="名字由来" tabindex="-1">名字由来 <a class="header-anchor" href="#名字由来" aria-label="Permalink to &quot;名字由来&quot;">​</a></h3><p>五道营胡同的名字源于明代军队的&quot;五道营&quot;驻地，营房与周边的胡同格局至今仍保留着旧时的肌理。</p><h3 id="从民居到文创街区" tabindex="-1">从民居到文创街区 <a class="header-anchor" href="#从民居到文创街区" aria-label="Permalink to &quot;从民居到文创街区&quot;">​</a></h3><p>历史上这里是普通居民的聚居区，胡同两侧多为传统四合院。近二十年来，一批设计师、艺术家和店主入驻，将老宅改造为咖啡馆、工作室和特色店铺，胡同逐渐演变为北京最具代表性的文创街区之一。</p><h2 id="街区特色" tabindex="-1">街区特色 <a class="header-anchor" href="#街区特色" aria-label="Permalink to &quot;街区特色&quot;">​</a></h2><h3 id="独立咖啡馆与甜品店" tabindex="-1">独立咖啡馆与甜品店 <a class="header-anchor" href="#独立咖啡馆与甜品店" aria-label="Permalink to &quot;独立咖啡馆与甜品店&quot;">​</a></h3><p>五道营胡同是北京咖啡馆密度最高的街区之一，各家小店风格迥异，从日式手冲到欧式烘焙，各有拥趸。</p><h3 id="手作工作室与设计小店" tabindex="-1">手作工作室与设计小店 <a class="header-anchor" href="#手作工作室与设计小店" aria-label="Permalink to &quot;手作工作室与设计小店&quot;">​</a></h3><p>胡同内分布着大量手作、古着、文创店铺，适合慢慢逛、慢慢淘，很多商品都是店主手工制作，别具一格。</p><h3 id="书店与画廊" tabindex="-1">书店与画廊 <a class="header-anchor" href="#书店与画廊" aria-label="Permalink to &quot;书店与画廊&quot;">​</a></h3><p>低调的书店和艺术空间隐藏在胡同深处，适合喜欢安静的游客驻足。</p><h2 id="游览攻略" tabindex="-1">游览攻略 <a class="header-anchor" href="#游览攻略" aria-label="Permalink to &quot;游览攻略&quot;">​</a></h2><h3 id="推荐路线" tabindex="-1">推荐路线 <a class="header-anchor" href="#推荐路线" aria-label="Permalink to &quot;推荐路线&quot;">​</a></h3><p><strong>半日路线</strong>：</p><p>五道营胡同西口 → 独立咖啡馆 → 手作小店 → 胡同深处 → 东口出 → 国子监街</p><h3 id="实用贴士" tabindex="-1">实用贴士 <a class="header-anchor" href="#实用贴士" aria-label="Permalink to &quot;实用贴士&quot;">​</a></h3><ol><li><strong>交通</strong>：地铁2号线安定门站下车步行约10分钟，或5号线雍和宫站步行约8分钟</li><li><strong>错峰</strong>：周末人较多，工作日上午最为安静</li><li><strong>拍照</strong>：胡同里的红墙、老门楼和咖啡馆门脸都很出片</li><li><strong>搭配</strong>：与国子监、孔庙、雍和宫连成一线，适合串联游玩</li></ol><h3 id="交通方式" tabindex="-1">交通方式 <a class="header-anchor" href="#交通方式" aria-label="Permalink to &quot;交通方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">路线</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>地铁</strong></td><td style="text-align:left;">2号线安定门站，或5号线雍和宫站</td></tr><tr><td style="text-align:left;"><strong>公交</strong></td><td style="text-align:left;">安定门内大街附近公交站步行可达</td></tr><tr><td style="text-align:left;"><strong>打车</strong></td><td style="text-align:left;">定位&quot;五道营胡同&quot;即可</td></tr></tbody></table><h2 id="周边景点" tabindex="-1">周边景点 <a class="header-anchor" href="#周边景点" aria-label="Permalink to &quot;周边景点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">景点</th><th style="text-align:center;">距离</th><th style="text-align:left;">特色</th></tr></thead><tbody><tr><td style="text-align:left;">国子监与孔庙</td><td style="text-align:center;">步行5分钟</td><td style="text-align:left;">古代最高学府</td></tr><tr><td style="text-align:left;">雍和宫</td><td style="text-align:center;">步行10分钟</td><td style="text-align:left;">藏传佛教寺院</td></tr><tr><td style="text-align:left;">地坛公园</td><td style="text-align:center;">步行15分钟</td><td style="text-align:left;">皇家祭祀地坛</td></tr><tr><td style="text-align:left;">南锣鼓巷</td><td style="text-align:center;">步行20分钟</td><td style="text-align:left;">经典胡同街区</td></tr></tbody></table><h2 id="文化意义" tabindex="-1">文化意义 <a class="header-anchor" href="#文化意义" aria-label="Permalink to &quot;文化意义&quot;">​</a></h2><p>五道营胡同是北京胡同更新与城市文化融合的缩影。它以最小的改造介入，保留了胡同的历史肌理，又注入了当代生活气息，成为&quot;老北京&quot;与&quot;新北京&quot;对话的地方。</p><hr><p><strong>📍 地址</strong>：北京市东城区五道营胡同 <strong>🚇 地铁</strong>：2号线安定门站 / 5号线雍和宫站</p><p><strong>💡 Tips</strong>：五道营的精华在支巷与门脸，不要只看主街，拐进小院常常别有洞天。</p>',34)])])}const f=e(n,[["render",o]]);export{x as __pageData,f as default};
